NOTE = {'sb7a3628': 'название — по содержанию и записи каталога библиотеки («Панасик дезертиры»): титульного листа в файле нет',
        'sb9049d8': 'титульный лист лежит в библиотеке отдельным файлом; название взято с него'}
def run():
    PRE = {'upp': 'p', 'up': 'u', 'tsp': 's'}
    books = {c: json.load(open(D5 + 'books_%s.json' % c, encoding='utf-8')) for c in PRE}
    done = 0
    for k, (src, commit, dst, au, title, kind, pub, year, q) in R.items():
        b = next(x for x in books[src] if x['n'] == k)
        key = k if src == dst else PRE[dst] + k[1:]
        man = json.load(open(D5 + 'manifest_%s.json' % dst, encoding='utf-8'))
        if any(m['key'] == key for m in man): continue
        out = '.work/d5/%s/lib/%s.pdf' % (dst, key); os.makedirs(os.path.dirname(out), exist_ok=True)
        r = subprocess.run(['git', 'show', '%s:.work/d5/%s/lib/%s.pdf' % (commit, src, k)], capture_output=True)
        if r.returncode or r.stdout[:4] != b'%PDF': print('  нет в истории:', k); continue
        open(out, 'wb').write(r.stdout)
        rec = dict(b, n=key, authors=au, title=title, kind=kind, pub=pub, year=year, q=q, how=NOTE.get(k) or T, general=False)
        rec.pop('off', None); rec['restored'] = True
        books[dst] = [x for x in books[dst] if x['n'] != key] + [rec]; done += 1
    for c in PRE: json.dump(books[c], open(D5 + 'books_%s.json' % c, 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
    print('возвращено изданий:', done)
if __name__ == '__main__': run()
